import threading

def reproduce(connect, service) -> str | None:
    import psycopg.errors as pg_errors
    # Try several independent keys; any double-charge proves the bug.
    # Each round fires N concurrent retries of the same idempotency key.
    for rnd in range(5):
        key = f"repro-key-{rnd}"
        account_id = 1
        amount = 10
        n = 8
        barrier = threading.Barrier(n)
        results = [None] * n

        def worker(i):
            try:
                with connect() as conn:
                    barrier.wait()
                    try:
                        results[i] = service.pay(conn, key, account_id, amount)
                    except (pg_errors.DeadlockDetected, pg_errors.SerializationFailure, pg_errors.UniqueViolation, pg_errors.CheckViolation) as e:
                        results[i] = e
            except Exception as e:
                try:
                    results[i] = e
                except Exception:
                    pass

        threads = [threading.Thread(target=worker, args=(i,)) for i in range(n)]
        for t in threads:
            t.start()
        for t in threads:
            t.join()

        true_count = sum(1 for r in results if r is True)
        # check DB row count
        try:
            with connect() as conn:
                row = conn.execute("SELECT COUNT(*) FROM payments WHERE idempotency_key = %s", (key,)).fetchone()
                db_count = row[0] if row else 0
        except Exception:
            continue

        if db_count > 1 or true_count > 1:
            return f"idempotency violated: payment {key} was charged {db_count} times ({true_count} callers returned True), must be charged exactly once"
    return None
